/* ГОСТ-оформление (Документы). 1) Список литературы по ГОСТ Р 7.0.100-2018: карточка источника или поиск по DOI и ISBN →
   запись, добавление в список, ссылка [N] в место курсора, упорядочение списка с перенумерацией ссылок в тексте.
   2) Нормоконтроль по ГОСТ 7.32-2017: страница, основной текст (по тому, как абзац виден человеку), структурные элементы,
   заголовки и нумерация разделов, подписи рисунков и таблиц, ссылки на рисунки, таблицы и источники, сокращения.
   Замечания — пометками поверх текста; «Исправить оформление» — поля, стили, нумерация страниц, заголовки, подписи. */
const ЗЕЛЁНЫЙ = '#2b8a3e', КРАСНЫЙ = '#c92a2a', СЕРЫЙ = '#868e96', ЖЁЛТЫЙ = '#e67700';
const Т = '–';                     /* тире ГОСТ Р 7.0.100: «. – » между областями */
const экран = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); } }
const чисто = s => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();

/* ================= библиографическая запись ================= */
/* «Иванов И. И.», «Иванов Иван Иванович», «Иванов, И.И.», «Ivanov I. I.» → {фамилия, инициалы} */
function автор(с){
  с = чисто(с).replace(/,/g, ' ').replace(/\s+/g, ' ');
  if(!с) return null;
  const ч = с.split(' ');
  const фамилия = ч[0];
  const инициалы = ч.slice(1).join(' ').replace(/([A-ZА-ЯЁ])[a-zа-яё]*\.?\s*-\s*([A-ZА-ЯЁ])[a-zа-яё]*\.?/g, '$1.-$2.')
    .split(/\s+|(?<=\.)(?=[A-ZА-ЯЁ])/).filter(Boolean).map(x => /\.-/.test(x) ? x : x[0].toUpperCase() + '.').join(' ');
  return {фамилия, инициалы};
}
const заголовокАвтора = а => а.фамилия + (а.инициалы ? ', ' + а.инициалы : '');
const подписьАвтора = а => (а.инициалы ? а.инициалы + ' ' : '') + а.фамилия;
function ответственность(авторы, лат){
  if(авторы.length <= 4) return авторы.map(подписьАвтора).join(', ');
  return авторы.slice(0, 3).map(подписьАвтора).join(', ') + (лат ? ' [et al.]' : ' [и др.]');
}
const стр = s => чисто(s).replace(/\s*[-–—]\s*/g, '–').replace(/^[СсPp]\.\s*/, '');
const дата = s => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); if(m) return m[3] + '.' + m[2] + '.' + m[1]; return чисто(s); };
const сегодня = () => { const t = new Date(); return String(t.getDate()).padStart(2, '0') + '.' + String(t.getMonth() + 1).padStart(2, '0') + '.' + t.getFullYear(); };
/* точка в конце области не удваивается: «…?» и «…!» остаются */
const область = s => { s = чисто(s); return s ? (/[.!?…]$/.test(s) ? s : s + '.') : ''; };
function запись(п){
  const вид = п.вид || 'Книга';
  const авторы = String(п.авторы || '').split(/\n|;/).map(автор).filter(Boolean);
  const з = чисто(п.заглавие);
  if(!з && !/Закон/.test(вид)) throw new Error('Впишите заглавие');
  const глава = авторы.length && авторы.length <= 3 ? заголовокАвтора(авторы[0]) + ' ' : '';
  const отв = авторы.length ? ' / ' + ответственность(авторы, !/[А-Яа-яЁё]/.test(з)) : '';
  const сеть = чисто(п.адрес) ? ' ' + Т + ' URL: ' + чисто(п.адрес) + ' (дата обращения: ' + (дата(п.обращение) || сегодня()) + ').' : '';
  const текст = п.видСодержания === false ? '' : ' ' + Т + ' Текст : ' + (чисто(п.адрес) ? 'электронный.' : 'непосредственный.');
  const выход = (город, изд, год) => [чисто(город) && чисто(изд) ? чисто(город) + ' : ' + чисто(изд) : чисто(город) || чисто(изд), чисто(год)].filter(Boolean).join(', ');
  let s;
  if(вид === 'Книга'){
    s = глава + з + (чисто(п.сведения) ? ' : ' + чисто(п.сведения) : '') + отв + (чисто(п.редактор) ? (отв ? ' ; ' : ' / ') + чисто(п.редактор) : '');
    s = область(s);
    if(чисто(п.издание)) s += ' ' + Т + ' ' + область(п.издание);
    if(выход(п.город, п.издательство, п.год)) s += ' ' + Т + ' ' + область(выход(п.город, п.издательство, п.год));
    if(чисто(п.страниц)) s += ' ' + Т + ' ' + чисто(п.страниц).replace(/\s*с\.?$/, '') + ' с.';
    if(чисто(п.isbn)) s += ' ' + Т + ' ISBN ' + чисто(п.isbn) + '.';
  } else if(вид === 'Статья в журнале' || вид === 'Статья в сборнике'){
    /* иностранный источник — обозначения по-латински: Vol., no., P. */
    const лат = !/[А-Яа-яЁё]/.test(з + чисто(п.источник));
    if(!чисто(п.источник)) throw new Error('Впишите название ' + (вид === 'Статья в журнале' ? 'журнала' : 'сборника'));
    s = глава + з + отв + ' // ' + чисто(п.источник);
    if(вид === 'Статья в сборнике'){
      if(чисто(п.сведения)) s += ' : ' + чисто(п.сведения);
      s = область(s);
      if(выход(п.город, п.издательство, п.год)) s += ' ' + Т + ' ' + область(выход(п.город, п.издательство, п.год));
    } else {
      s = область(s);
      if(чисто(п.год)) s += ' ' + Т + ' ' + чисто(п.год) + '.';
      const тн = [чисто(п.том) ? (лат ? 'Vol. ' : 'Т. ') + чисто(п.том) : '', чисто(п.номер) ? (лат ? 'no. ' : '№ ') + чисто(п.номер) : ''].filter(Boolean).join(', ');
      if(тн) s += ' ' + Т + ' ' + тн + '.';
    }
    if(чисто(п.страницы)) s += ' ' + Т + (лат ? ' P. ' : ' С. ') + стр(п.страницы) + '.';
    if(чисто(п.doi)) s += ' ' + Т + ' DOI ' + чисто(п.doi).replace(/^https?:\/\/(dx\.)?doi\.org\//i, '') + '.';
  } else if(вид === 'Электронный ресурс (сайт)'){
    if(!чисто(п.адрес)) throw new Error('Впишите адрес (URL)');
    s = глава + з + (чисто(п.источник) ? ' // ' + чисто(п.источник) : '') + ' : [сайт]' + отв;
    s = область(s);
    const гг = [чисто(п.город), чисто(п.год)].filter(Boolean).join(', ');
    if(гг) s += ' ' + Т + ' ' + область(гг);
  } else if(вид === 'Закон, нормативный акт'){
    if(!чисто(п.заглавие) || !чисто(п.видАкта)) throw new Error('Впишите заглавие и вид акта');
    s = з + ' : ' + чисто(п.видАкта) + (чисто(п.датаАкта) ? ' от ' + дата(п.датаАкта) : '') + (чисто(п.номерАкта) ? ' № ' + чисто(п.номерАкта) : '');
    if(чисто(п.источник)){
      s += ' // ' + чисто(п.источник);
      s = область(s);
      if(чисто(п.год)) s += ' ' + Т + ' ' + чисто(п.год) + '.';
      if(чисто(п.номер)) s += ' ' + Т + ' № ' + чисто(п.номер) + '.';
      if(чисто(п.статья)) s += ' ' + Т + ' Ст. ' + чисто(п.статья).replace(/^Ст\.?\s*/i, '') + '.';
    } else s = область(s);
  } else if(вид === 'Стандарт (ГОСТ)'){
    if(!чисто(п.обозначение)) throw new Error('Впишите обозначение стандарта: ГОСТ Р 7.0.100–2018');
    s = чисто(п.обозначение).replace(/(\d)\s*[-–—]\s*(\d{2,4})$/, '$1–$2') + '. ' + з + ' : ' + (чисто(п.видСтандарта) || 'национальный стандарт Российской Федерации') + ' : издание официальное';
    if(чисто(п.введён)) s += ' : дата введения ' + чисто(п.введён).replace(/^(\d{2})\.(\d{2})\.(\d{4})$/, '$3-$2-$1');
    s = область(s);
    if(выход(п.город, п.издательство, п.год)) s += ' ' + Т + ' ' + область(выход(п.город, п.издательство, п.год));
    if(чисто(п.страниц)) s += ' ' + Т + ' ' + чисто(п.страниц).replace(/\s*с\.?$/, '') + ' с.';
  } else if(вид === 'Диссертация, автореферат'){
    const авто = п.диссВид === 'автореферат';
    s = глава + з + (чисто(п.специальность) ? ' : специальность ' + чисто(п.специальность) : '') + ' : ' + (авто ? 'автореферат диссертации' : 'диссертация') + ' на соискание учёной степени ' + (чисто(п.степень) || 'кандидата наук') + отв + (чисто(п.защита) ? ' ; ' + чисто(п.защита) : '');
    s = область(s);
    const гг = [чисто(п.город), чисто(п.год)].filter(Boolean).join(', ');
    if(гг) s += ' ' + Т + ' ' + область(гг);
    if(чисто(п.страниц)) s += ' ' + Т + ' ' + чисто(п.страниц).replace(/\s*с\.?$/, '') + ' с.';
  } else throw new Error('Не знаю вид источника «' + вид + '»');
  return (s + сеть + текст).replace(/\.\./g, '.').replace(/\s+/g, ' ').trim();
}
function карточка(){ const п = параметры({}); п.видСодержания = !!п.видСодержания; return п; }
function Предпросмотр(){
  try { панель.поле('запись', [{текст: запись(карточка())}]); }
  catch(e){ панель.поле('запись', [{текст: e.message, цвет: СЕРЫЙ}]); }
}

/* ================= список литературы в документе ================= */
const ЗАГЛАВИЕ_СПИСКА = /^(список\s+(использованных\s+|используемых\s+)?(источников|литературы)(\s+и\s+литературы)?|библиографический\s+список|литература|список\s+источников)\s*$/i;
const заголовок = б => /^H[1-6]$/.test(б.тег) || (б.тег === 'P' && б.текст.length < 120 && б.текст === б.текст.toUpperCase() && /[А-ЯЁ]{4}/.test(б.текст));
const безТегов = h => String(h).replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
function найтиСписок(блоки){
  const з = блоки.findIndex(б => заголовок(б) && ЗАГЛАВИЕ_СПИСКА.test(чисто(б.текст).replace(/[.:]$/, '')));
  if(з < 0) return null;
  let конец = блоки.length;
  for(let i = з + 1; i < блоки.length; i++) if(/^H[1-6]$/.test(блоки[i].тег) || (заголовок(блоки[i]) && /^приложение/i.test(блоки[i].текст.trim()))){ конец = i; break; }
  const записи = [];          /* {блок, li (номер пункта в списке) | null, текст} */
  for(let i = з + 1; i < конец; i++){
    const б = блоки[i];
    if(/^(OL|UL)$/.test(б.тег)){ const пункты = (б.html.match(/<li[^>]*>[\s\S]*?<\/li>/gi) || []).map(безТегов); пункты.forEach((т, k) => записи.push({блок: i, li: k, текст: чисто(т)})); }
    else if(б.тег === 'P' && чисто(б.текст)) записи.push({блок: i, li: null, текст: чисто(б.текст).replace(/^\d+[.)]\s*/, '')});
  }
  return {заголовок: з, конец, записи};
}
function обновитьИсточники(){
  const с = найтиСписок(документ.блоки);
  панель.список('источники', с ? с.записи.map((з, i) => (i + 1) + '. ' + (з.текст.length > 90 ? з.текст.slice(0, 89) + '…' : з.текст)) : []);
  return с;
}
async function Добавить(){ return безСбоя(() => {
  const текст = запись(карточка());
  const блоки = документ.блоки, с = найтиСписок(блоки);
  let n;
  if(!с){
    документ.вставитьВКонец('<h1>СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ</h1>');
    документ.вставитьВКонец('<p>1. ' + экран(текст) + '</p>');
    n = 1;
  } else {
    n = с.записи.length + 1;
    const посл = с.записи[с.записи.length - 1];
    if(посл && посл.li !== null){ const б = блоки[посл.блок]; документ.правитьБлок(посл.блок, {html: б.html.replace(/<\/(ol|ul)>\s*$/i, '') + '<li>' + экран(текст) + '</li>'}); }
    else документ.вставить(посл ? посл.блок + 1 : с.заголовок + 1, '<p>' + n + '. ' + экран(текст) + '</p>');
  }
  обновитьИсточники();
  панель.сообщение('Источник № ' + n + ' добавлен в список. Ссылка на него в тексте — [' + n + ']');
}); }
function ВставитьЗапись(){ return безСбоя(() => { документ.вставитьВКурсор(экран(запись(карточка()))); }); }
function ВставитьСсылку(){ return безСбоя(() => {
  const п = параметры({});
  const n = parseInt(п.источники, 10);
  if(!n) throw new Error('Выберите источник в списке');
  const с = чисто(п.страница);
  документ.вставитьВКурсор('[' + n + (с ? ', с. ' + стр(с) : '') + ']');
  вставлено = документ.блоки[0] || null;
  панель.сообщение('Ссылка [' + n + (с ? ', с. ' + стр(с) : '') + '] — в месте курсора');
}); }
function ОбновитьИсточники(){ const с = обновитьИсточники(); панель.сообщение(с ? 'Источников в списке: ' + с.записи.length : 'Раздела «Список использованных источников» в документе нет'); }

/* ссылки [1], [2, с. 15], [3; 5], [4–6] в тексте вне списка */
const ССЫЛКА = /\[(\d+(?:\s*[,;–—-]\s*\d+)*)(\s*,\s*(?:с|С|p|P)\.\s*[\d–—-]+)?\]/g;
function номераСсылки(список){
  const out = [];
  for(const ч of список.split(/\s*[,;]\s*/)){ const м = ч.match(/^(\d+)\s*[–—-]\s*(\d+)$/); if(м){ for(let k = +м[1]; k <= +м[2] && k - м[1] < 200; k++) out.push(k); } else if(/^\d+$/.test(ч)) out.push(+ч); }
  return out;
}
function сжатьНомера(н){
  н = [...new Set(н)].sort((a, b) => a - b); const out = [];
  for(let i = 0; i < н.length; i++){ let j = i; while(j + 1 < н.length && н[j + 1] === н[j] + 1) j++; out.push(j - i >= 2 ? н[i] + '–' + н[j] : j > i ? н[i] + ', ' + н[j] : String(н[i])); i = j; }
  return out.join(', ');
}
/* После вставки в место курсора поток не знает, что стало с абзацем: страница присылает свежий снимок документа
   только после правки человека. Пока снимок прежний (те же объекты блоков), переписывать абзацы со ссылками нельзя —
   вставленное пропало бы. */
let вставлено = null;
const снимокУстарел = () => вставлено !== null && документ.блоки[0] === вставлено;
/* упорядочить: по алфавиту (русские, потом латиница) или по первой ссылке в тексте; ссылки перенумеровать */
async function Упорядочить(){ return безСбоя(() => {
  const п = параметры({});
  if(снимокУстарел()) throw new Error('Плагин ещё не видит только что вставленную ссылку: сделайте любую правку в тексте (например, пробел и Backspace) и нажмите «Упорядочить список» ещё раз.');
  const блоки = документ.блоки, с = найтиСписок(блоки);
  if(!с || !с.записи.length) throw new Error('В документе нет списка источников');
  if(new Set(с.записи.map(з => з.блок)).size !== с.записи.length && с.записи.some(з => з.li === null)) throw new Error('Список смешанный (и абзацы, и нумерованный список) — приведите к одному виду');
  const первая = new Map(); let k = 0;
  блоки.forEach((б, i) => { if(i >= с.заголовок && i < с.конец) return; ССЫЛКА.lastIndex = 0; let м; while((м = ССЫЛКА.exec(б.текст))) for(const n of номераСсылки(м[1])) if(!первая.has(n)) первая.set(n, k++); });
  const порядок = с.записи.map((з, i) => ({з, старый: i + 1}));
  if(п.порядок === 'По первой ссылке в тексте') порядок.sort((a, b) => (первая.has(a.старый) ? первая.get(a.старый) : 1e9 + a.старый) - (первая.has(b.старый) ? первая.get(b.старый) : 1e9 + b.старый));
  else порядок.sort((a, b) => { const la = /^[A-Za-z]/.test(a.з.текст), lb = /^[A-Za-z]/.test(b.з.текст); return la !== lb ? (la ? 1 : -1) : a.з.текст.localeCompare(b.з.текст, la ? 'en' : 'ru'); });
  const карта = new Map(порядок.map((x, i) => [x.старый, i + 1]));
  if(порядок.every((x, i) => x.старый === i + 1)){ панель.сообщение('Список уже в нужном порядке'); return; }
  /* ссылки в тексте — по html, только в тексте между тегами */
  let ссылок = 0;
  блоки.forEach((б, i) => {
    if(i >= с.заголовок && i < с.конец) return;
    ССЫЛКА.lastIndex = 0; if(!ССЫЛКА.test(б.текст)) return;
    const html = б.html.split(/(<[^>]+>)/).map(кус => кус.startsWith('<') ? кус : кус.replace(ССЫЛКА, (всё, сп, стр2) => { ссылок++; return '[' + сжатьНомера(номераСсылки(сп).map(n => карта.get(n) || n)) + (стр2 || '') + ']'; })).join('');
    if(html !== б.html) документ.правитьБлок(i, {html});
  });
  /* сам список: абзацы — заново по порядку; нумерованный список — пункты в новом порядке */
  if(с.записи[0].li !== null){
    const i = с.записи[0].блок, б = блоки[i];
    const пункты = б.html.match(/<li[^>]*>[\s\S]*?<\/li>/gi) || [];
    документ.правитьБлок(i, {html: порядок.map(x => пункты[x.з.li]).join('')});
  } else {
    const html = с.записи.map(з => блоки[з.блок].html.replace(/^(\s*(?:<[^>]+>)*\s*)\d+[.)]\s*/, '$1'));
    const первый = с.записи[0].блок;
    for(let j = с.записи.length - 1; j >= 0; j--) документ.удалить(с.записи[j].блок);
    порядок.forEach((x, j) => документ.вставить(первый + j, '<p>' + (j + 1) + '. ' + html[x.старый - 1] + '</p>'));
  }
  обновитьИсточники();
  панель.сообщение('Список упорядочен (' + (п.порядок || 'по алфавиту').toLowerCase() + '), ссылок в тексте перенумеровано: ' + ссылок);
}); }

/* ================= поиск по DOI и ISBN ================= */
async function Найти(){ return безСбоя(async () => {
  const п = параметры({});
  const ключ = чисто(п.ключ);
  if(!ключ) throw new Error('Впишите DOI (10.xxxx/…) или ISBN');
  const doi = (ключ.match(/10\.\d{4,9}\/\S+/) || [])[0];
  const isbn = ключ.replace(/[^\dXx]/g, '');
