/* исправить: поля, стили, нумерация страниц, заголовки структурных элементов, подписи */
async function Исправить(){ return безСбоя(async () => {
  const п = параметры({});
  if(!(await диалог.вопрос('Задать поля страницы, стили «Обычный» и заголовков, нумерацию страниц, исправить заголовки структурных элементов и подписи рисунков и таблиц? Всё отменяется одной кнопкой «Отменить».'))) return;
  const нужно = поляИз(п.поля), кегль = Math.max(12, +п.кегль || 12);
  const стр0 = документ.страница || {}, кт = стр0.колонтитулы || {};
  const нов = {размер: 'A4', ориентация: 'книжная', поля: нужно};
  /* номер — только цифрой и только внизу: там, где он был (слева или справа), иначе справа */
  нов.колонтитулы = {первая: 'без номера'};
  for(const k of ['верх', 'верхСправа']) if(/\{страница\}/.test(кт[k] || '')) нов.колонтитулы[k] = чисто(кт[k].replace(/(стр(аница|\.)?\s*)?\{страница\}(\s*(из|\/)\s*\{всего\})?/gi, ''));
  if(/\{страница\}/.test(кт.низ || '')) нов.колонтитулы.низ = '{страница}';
  else нов.колонтитулы.низСправа = '{страница}';
  документ.задатьСтраницу(нов);
  документ.задатьСтиль('Обычный', {шрифт: 'Times New Roman', кегль, интервал: 1.5, отступПервой: 12.5, выравнивание: 'ширина', перед: 0, после: 0});
  документ.задатьСтиль('Заголовок 1', {шрифт: 'Times New Roman', кегль, жирный: true, выравнивание: 'центр', отступПервой: 0, интервал: 1.5});
  документ.задатьСтиль('Заголовок 2', {шрифт: 'Times New Roman', кегль, жирный: true, выравнивание: 'лево', отступПервой: 12.5, интервал: 1.5});
  документ.задатьСтиль('Заголовок 3', {шрифт: 'Times New Roman', кегль, жирный: true, выравнивание: 'лево', отступПервой: 12.5, интервал: 1.5});
  let правок = 0;
  документ.блоки.forEach((б, i) => {
    const т = чисто(б.текст);
    if(заголовок(б) && т){
      const верх = т.toUpperCase().replace(/\.$/, '');
      if(ВСЕ_СТРУКТУРНЫЕ.test(верх) && т !== верх){ документ.правитьБлок(i, {текст: верх}); правок++; return; }
      if(/^H/.test(б.тег) && /[^.]\.$/.test(т)){ документ.правитьБлок(i, {текст: т.replace(/\.$/, '').replace(/^(\d+(?:\.\d+)*)\.\s/, '$1 ')}); правок++; return; }
      if(/^H/.test(б.тег) && /^\d+(?:\.\d+)*\.\s/.test(т)){ документ.правитьБлок(i, {текст: т.replace(/^(\d+(?:\.\d+)*)\.\s/, '$1 ')}); правок++; return; }
    }
    const м = б.тег === 'P' && т.match(/^(Рисунок|Рис\.?|Таблица|Табл\.?)\s*(\d+(?:\.\d+)?|[А-ЯA-Z]\.\d+)\s*(?:([-–—.:])\s*)?(.*)$/);
    if(м){ const вид = /^Рис/.test(м[1]) ? 'Рисунок' : 'Таблица'; const н = вид + ' ' + м[2] + (м[4] ? ' – ' + м[4].replace(/\.$/, '') : ''); if(н !== т){ документ.правитьБлок(i, {текст: н}); правок++; } }
  });
  панель.сообщение('Оформление задано: поля ' + [нужно.лево, нужно.право, нужно.верх, нужно.низ].join('/') + ' мм, Times New Roman ' + кегль + ' пт, интервал 1,5, отступ 12,5 мм; правок в тексте: ' + правок + '. Абзацы с ручным оформлением поправьте «Очистить формат».');
  if(замечания.length) await Проверить();
}); }
